window.SKILLS=[{"n":"Lumberjack","fr":"Bûcheron","t":"Core","a":["Core"],"c":1,"r":3,"en":"At maximum rank (3): Tools deal 30% increased damage against wood. This includes trees and wooden terrain. Per rank: 10% damage per level.","d":"Les outils infligent +10 % de dégâts au bois par rang (+30 % au rang 3) : arbres et terrain en bois. Coupe plus vite le bois.","tags":["gather"],"p":3},{"n":"Quality Gear","fr":"Équipement de qualité","t":"Core","a":["Core"],"c":1,"r":1,"en":"Tools have a 20% chance to restore 1 durability on hit.","d":"Les outils ont 20 % de chances de regagner 1 point de durabilité à chaque coup.","tags":["gather"],"p":2},{"n":"Miner","fr":"Mineur","t":"Core","a":["Core"],"c":2,"r":1,"en":"Mining resources has a 10% chance to grant one additional resource.","d":"En minant, 10 % de chances d'obtenir une ressource supplémentaire.","tags":["gather"],"p":3},{"n":"Mason","fr":"Maçon","t":"Core","a":["Core"],"c":1,"r":3,"en":"At maximum rank (3): Tools deal 30% increased damage against stone. This includes stone terrain and gemstone veins. Per rank: 10% damage per level.","d":"Les outils infligent +10 % de dégâts à la pierre par rang (+30 % au rang 3) : roche, filons de minerai et de gemmes.","tags":["gather"],"p":3},{"n":"Power Parry","fr":"Parade de puissance","t":"Core","a":["Core"],"c":1,"r":3,"en":"At maximum rank (3): Your Parry Power is increased by 30%. Parry You can block when equipped with any Melee weapon, Ward, or Shield. A well-timed block will parry the attack and fill up the enemy's Stun Bar. Wait to see a flash on the enemy or projectile to perform a parry. Overpower Attacking blocking enemies or parrying their attacks fills their Stun Bar until they become overpowered. Overpowered enemies are open for Merciless Attacks. Per rank: 10% Parry Power per level.","d":"Augmente la puissance de tes parades de +10 % par rang (+30 % au rang 3). Une parade réussie remplit la jauge d'étourdissement de l'ennemi.","tags":["melee","parry"],"p":2},{"n":"Merciless Attack","fr":"Attaque impitoyable","t":"Core","a":["Core"],"c":2,"r":1,"en":"Perform a Merciless Attack by pressing [E] to deal massive damage to an enemy you've empowered.\nOverpower\nTo overpower an enemy, fill their stun bar by attacking while they block or by parrying their attacks.","d":"Débloque l'Attaque impitoyable : quand un ennemi est « submergé » (jauge d'étourdissement pleine), appuie sur [E] pour lui infliger des dégâts énormes. Indispensable au corps à corps.","tags":["melee","parry"],"p":3},{"n":"Saviour","fr":"Sauveur","t":"Core","a":["Core"],"c":1,"r":1,"en":"You only need 3 instead of 6 seconds to revive an ally.","d":"Tu relèves un allié en 3 secondes au lieu de 6.","tags":["coop"],"p":1},{"n":"Well Rested","fr":"Bien reposé","t":"Core","a":["Core"],"c":1,"r":1,"en":"The base duration for the Rested buff is increased by 5 Minutes.\nIncrease the Comfort in your home to further increase the duration.","d":"La durée de base du bonus « Reposé » augmente de 5 minutes (plus d'endurance). Le confort de ta base augmente encore la durée.","tags":["survival"],"p":2},{"n":"Backstab Damage","fr":"Dégâts dans le dos","t":"Core","a":["Core"],"c":2,"r":1,"en":"Increase the damage you deal from behind by 25%.","d":"+25 % de dégâts quand tu frappes un ennemi dans le dos.","tags":["dagger","stealth"],"p":2},{"n":"Sneak Attack","fr":"Attaque furtive","t":"Core","a":["Core"],"c":3,"r":1,"en":"Perform a Sneak Attack by sneaking up to an unaware enemy and pressing [E].\nSneak Attack deals +900% increased damage.","d":"Débloque l'Attaque furtive : approche-toi accroupi d'un ennemi qui ne t'a pas vu et appuie sur [E] pour +900 % de dégâts.","tags":["stealth","dagger","bow"],"p":2},{"n":"Fisherman's Resolve","fr":"Résolution du pêcheur","t":"Core","a":["Core"],"c":5,"r":1,"en":"Increases your Fishing Endurance by 30%.\nAllows for extended battles with hooked fish.","d":"+30 % d'endurance de pêche : tu peux combattre plus longtemps un poisson ferré.","tags":["gather"],"p":1},{"n":"Opportunity","fr":"Opportunité","t":"Core","a":["Core"],"c":1,"r":3,"en":"At maximum rank (3): Increases the damage multiplier of Merciless Attacks by 120%. Per rank: 40% damage per level.","d":"Augmente le multiplicateur de l'Attaque impitoyable (+40 % par rang, +120 % au rang 3).","tags":["melee","parry"],"p":2},{"n":"Giant Slayer Hook","fr":"Crochet de tueur géant","t":"Core","a":["Core"],"c":3,"r":1,"en":"Use your Grappling Hook to pull yourself towards large enemies during combat.","d":"Ton grappin peut te tirer vers les gros ennemis pendant le combat.","tags":["melee"],"p":1},{"n":"Grounding Hook","fr":"Grappin de mise à la terre","t":"Core","a":["Core"],"c":4,"r":1,"en":"Use your Grappling Hook to pull flying enemies towards you during combat.","d":"Ton grappin peut attirer les ennemis volants vers toi pendant le combat.","tags":["melee"],"p":1},{"n":"Dexterity","fr":"Dextérité","t":"Ranger","a":["Assassin","Ranger","Beastmaster","Survivor"],"c":1,"r":1,"en":"Increases your Dexterity attribute by 1\nIncreases Bow and Dagger damage by 5% per Attribute Point","d":"Nœud d'attribut : +1 Dextérité = +5 % de dégâts à l'arc et aux dagues.","tags":["bow","dagger"],"p":2},{"n":"Airborne","fr":"Aérien","t":"Ranger","a":["Assassin"],"c":1,"r":3,"en":"At maximum rank (3): Gliders consume 36% less Stamina. Per rank: 12% cost reduction per level.","d":"Le planeur consomme 12 % d'endurance en moins par rang (-36 % au rang 3). Excellent pour explorer.","tags":["explore"],"p":3},{"n":"Endurance","fr":"Résistance","t":"Ranger","a":["Assassin","Beastmaster","Survivor"],"c":1,"r":1,"en":"Increases your Endurance attribute by 1\nIncreases Stamina by 10 per Attribute Point","d":"Nœud d'attribut : +1 Endurance = +10 d'endurance (stamina).","tags":["survival","explore"],"p":2},{"n":"Sniper","fr":"Sniper","t":"Ranger","a":["Assassin"],"c":2,"r":3,"en":"At maximum rank (3): Critical Strike chance with Bows is increased by 6%. Per rank: 2% Critical Strike chance per level.","d":"+2 % de chances de coup critique à l'arc par rang (+6 % au rang 3).","tags":["bow"],"p":2},{"n":"Vitality Surge","fr":"Surcroît de vitalité","t":"Ranger","a":["Assassin"],"c":1,"r":3,"en":"At maximum rank (3): Critical Strikes with Bows, Daggers and Throwables restore 9 Stamina. Per rank: 3 Stamina per level.","d":"Les coups critiques à l'arc, aux dagues et aux armes de jet rendent 3 d'endurance par rang (9 au rang 3).","tags":["bow","dagger"],"p":2},{"n":"Blessed Arrows","fr":"Flèches enchantées","t":"Ranger","a":["Assassin"],"c":1,"r":3,"en":"At maximum rank (3): Critical Strikes with Bows restore 24 Mana. Per rank: 8 Mana per level.","d":"Les coups critiques à l'arc rendent 8 de mana par rang (24 au rang 3). Utile pour un hybride arc + magie.","tags":["bow","magic"],"p":1},{"n":"Bounty Bonanza","fr":"Bonus de prime","t":"Ranger","a":["Assassin"],"c":2,"r":1,"en":"After defeating a Fell enemy with a headshot your group gains an additional 5 Experience Points.","d":"Tuer un ennemi Corrompu (Fell) d'un tir à la tête donne +5 XP à ton groupe.","tags":["bow"],"p":1},{"n":"Shell Shock","fr":"Sous le choc","t":"Ranger","a":["Assassin"],"c":3,"r":1,"en":"Infuse your ranged explosives with mana. They now stun enemies for up to 1 second.\nMana Cost: 5 per stunned enemy","d":"Tes explosifs à distance étourdissent les ennemis jusqu'à 1 seconde (coûte 5 mana par ennemi étourdi).","tags":["bow"],"p":1},{"n":"Ricochets","fr":"Ricochets","t":"Ranger","a":["Assassin"],"c":4,"r":1,"en":"For every target you hit with an Exploding Arrow, its damage is increased by 1%.","d":"Chaque cible touchée par une flèche explosive augmente ses dégâts de 1 %.","tags":["bow"],"p":1},{"n":"Graceful Stride","fr":"La foulée gracieuse","t":"Ranger","a":["Assassin"],"c":5,"r":1,"en":"Gain one point of Dexterity for every two levels of the Flame.","d":"Tu gagnes 1 point de Dextérité tous les 2 niveaux de Flamme. Gros bonus passif pour arc/dagues.","tags":["bow","dagger"],"p":3},{"n":"Chain Reaction","fr":"Réaction en chaîne","t":"Ranger","a":["Assassin"],"c":5,"r":1,"en":"Every enemy hit with an Exploding Arrow has a 20% chance to trigger a secondary explosion for 50% damage in a small radius.","d":"Chaque ennemi touché par une flèche explosive a 20 % de chances de déclencher une seconde explosion (50 % des dégâts).","tags":["bow"],"p":2},{"n":"Silent Stride","fr":"La foulée silencieuse","t":"Ranger","a":["Assassin","Ranger"],"c":1,"r":1,"en":"Increases your movement speed while sneaking.","d":"Tu te déplaces plus vite en mode furtif (accroupi).","tags":["stealth"],"p":1},{"n":"Updraft","fr":"Courant ascendant","t":"Ranger","a":["Assassin","Trickster"],"c":4,"r":1,"en":"Jumping while gliding gives you a height boost. This skill can be used once per flight.\nCost: 100 Mana","d":"En planant, sauter te donne un boost de hauteur (une fois par vol, coûte 100 mana). Top pour l'exploration.","tags":["explore","magic"],"p":2},{"n":"Marksman","fr":"Tireur d'élite (Marksman)","t":"Ranger","a":["Ranger"],"c":1,"r":3,"en":"At maximum rank (3): Damage with Bows is increased by 15%. Per rank: 5% damage per level.","d":"+5 % de dégâts à l'arc par rang (+15 % au rang 3).","tags":["bow"],"p":3},{"n":"Counter Battery","fr":"Contre-batterie","t":"Ranger","a":["Ranger"],"c":1,"r":3,"en":"At maximum rank (3): Damage against ranged enemies is increased by 24%. Per rank: 8% damage per level.","d":"+8 % de dégâts contre les ennemis à distance par rang (+24 % au rang 3).","tags":["bow"],"p":2},{"n":"Eagles Bane","fr":"Le fauve de l'aigle","t":"Ranger","a":["Ranger"],"c":3,"r":1,"en":"Damage against flying enemies increased by 30%.","d":"+30 % de dégâts contre les ennemis volants.","tags":["bow"],"p":1},{"n":"Bee Sting","fr":"Piqûre d'abeille","t":"Ranger","a":["Ranger"],"c":3,"r":1,"en":"When you draw your bow while in the air, your fall is slowed down for a short time. Every shot gives you a small push to get more air time.\nCost: 10 stamina per second","d":"Bander ton arc en l'air ralentit ta chute ; chaque tir te donne une petite poussée vers le haut (10 endurance/s).","tags":["bow","explore"],"p":2},{"n":"Sharpshooter","fr":"Tireur d'élite (Sharpshooter)","t":"Ranger","a":["Ranger"],"c":2,"r":1,"en":"All ranged damage is increased by an additional 20%","d":"+20 % de dégâts à distance supplémentaires.","tags":["bow"],"p":3},{"n":"Skill Shot","fr":"Coup d'adresse","t":"Ranger","a":["Ranger"],"c":1,"r":1,"en":"The Skill Shot skill improves the damage of Skillshots, i.e. using a bow to strike an enemy's weak point. For many enemies in Enshrouded, this is simply the head, but not always--the weak point of the Fell Monstrosity, for example, is its open mouth.\nThere are three levels to the skill, and each improves Skillshot damage by 20%, maxing out at an increase of 60%.","d":"Améliore les « tirs d'adresse » : toucher le point faible d'un ennemi (souvent la tête) avec une flèche. Les tirs d'adresse font déjà +100 % de dégâts.","tags":["bow"],"p":3},{"n":"Multi Shot","fr":"Multi-tirs","t":"Ranger","a":["Ranger"],"c":4,"r":1,"en":"When using regular arrows there is a 20% chance to spawn a flurry of arrows that spread slightly.\nThis will cost additional arrows, but will not trigger on special arrows.","d":"Les flèches normales ont 20 % de chances de tirer une volée de flèches (consomme des flèches en plus). Ne marche pas avec les flèches spéciales.","tags":["bow"],"p":3},{"n":"Multi Shot Spread","fr":"Répartition multi-tirs","t":"Ranger","a":["Ranger"],"c":3,"r":1,"en":"Adds a 25% chance to spawn an additional projectile to your \"flurry of arrows\" from the \"Multi Shot\" skill.\nThis additional projectile does not subtract from your stack of ammunition.","d":"Ajoute 25 % de chances d'une flèche bonus dans la volée de Multi-tirs, sans consommer de munition.","tags":["bow"],"p":2},{"n":"Multi Shot Trigger","fr":"Déclencheur multi-tirs","t":"Ranger","a":["Ranger"],"c":3,"r":1,"en":"ALL arrows, including special arrows, can trigger \"Multi Shot\".\nThe special Multi Shot projectiles will subtract from your stack of ammunition.","d":"TOUTES les flèches, y compris spéciales, peuvent déclencher Multi-tirs (consomme les flèches spéciales).","tags":["bow"],"p":2},{"n":"Ranger","fr":"Archer","t":"Ranger","a":["Ranger"],"c":2,"r":1,"en":"+2 Endurance\n+2 Dexterity\n+5 Stamina Recharge\n+5% Critical Chance\n+5% Critical Damage","d":"Nœud majeur : +2 Endurance, +2 Dextérité, +5 récupération d'endurance, +5 % chances de critique, +5 % dégâts critiques.","tags":["bow","dagger"],"p":3},{"n":"Eagle Eye","fr":"Oeil d'aigle","t":"Ranger","a":["Ranger","Beastmaster"],"c":3,"r":1,"en":"Greatly increases the zoom while aiming with a bow.","d":"Zoom beaucoup plus fort en visant à l'arc. Pratique pour les tirs à la tête de loin.","tags":["bow"],"p":2},{"n":"Snake Eater","fr":"Mangeur de serpent","t":"Ranger","a":["Beastmaster"],"c":2,"r":3,"en":"At maximum rank (3): Increases your Poison Resistance by 12%, which reduces the amount of Poison damage received. Poison damage bypasses armor and can only be mitigated by Poison Resistance. Per rank: 4% Resistance per level.","d":"+4 % de résistance au poison par rang (+12 % au rang 3). Le poison ignore l'armure.","tags":["survival"],"p":1},{"n":"Mithridatist","fr":"Immunisé","t":"Ranger","a":["Beastmaster"],"c":2,"r":1,"en":"Your poison resistance is increased by an additional 10%.\nYou also gain a 25% chance to avoid being poisoned.","d":"+10 % de résistance au poison et 25 % de chances d'éviter l'empoisonnement.","tags":["survival"],"p":1},{"n":"Calm Spirit","fr":"Esprit calme","t":"Ranger","a":["Beastmaster"],"c":3,"r":1,"en":"Wild Animals within 50 meters will no longer attack you unless provoked. Does not affect animals corrupted by the Shroud.","d":"Les animaux sauvages dans un rayon de 50 m ne t'attaquent plus sauf si tu les provoques (pas les animaux corrompus).","tags":["explore"],"p":2},{"n":"Vukah Language","fr":"Langue vukah","t":"Ranger","a":["Beastmaster"],"c":3,"r":1,"en":"Vukah within 50 meters will no longer attack you unless provoked.","d":"Les Vukah dans un rayon de 50 m ne t'attaquent plus sauf si tu les provoques.","tags":["explore"],"p":1},{"n":"Beast Master","fr":"Maître des bêtes","t":"Ranger","a":["Beastmaster"],"c":4,"r":1,"en":"When you are targeted by an attack, Wild Animals within 50 meters will attack the enemy.","d":"Quand on t'attaque, les animaux sauvages à moins de 50 m attaquent ton agresseur.","tags":["explore"],"p":1},{"n":"Vukah Culture","fr":"Culture vukah","t":"Ranger","a":["Beastmaster"],"c":4,"r":1,"en":"When you are targeted by an attack, Vukah within 50 meters will attack the enemy.","d":"Quand on t'attaque, les Vukah à moins de 50 m attaquent ton agresseur.","tags":["explore"],"p":1},{"n":"Endurance Of The Flame","fr":"L'endurance de la flamme","t":"Ranger","a":["Beastmaster"],"c":5,"r":1,"en":"Gain one point of Endurance for every two levels of the Flame.","d":"Tu gagnes 1 point d'Endurance tous les 2 niveaux de Flamme.","tags":["survival","explore"],"p":2},{"n":"Inner Fires","fr":"Flammes intérieures","t":"Ranger","a":["Beastmaster","Survivor"],"c":1,"r":1,"en":"Maximum Shroud Time increased by 2 minutes, allowing you to explore for longer.\nShroud Time\nShould this time run out, the Shroud will consume you.","d":"+2 minutes de temps maximum dans la Brume. Très utile au début pour farmer dans la Brume.","tags":["explore","gather"],"p":3},{"n":"Relentless Flame","fr":"Flamme acharnée","t":"Ranger","a":["Beastmaster","Survivor"],"c":4,"r":1,"en":"Maximum Shroud Time increased by 5 minutes, allowing you to explore for longer.\nShroud Time\nShould this time run out, the Shroud will consume you.","d":"+5 minutes de temps maximum dans la Brume.","tags":["explore","gather"],"p":3},{"n":"Runner","fr":"Coureur","t":"Ranger","a":["Survivor"],"c":1,"r":1,"en":"Sprinting speed increased by 10% and stamina consumption decreased by 10%","d":"+10 % de vitesse de sprint et -10 % de consommation d'endurance en sprint.","tags":["explore"],"p":3},{"n":"Wanderlust","fr":"Envie d'évasion","t":"Ranger","a":["Survivor"],"c":3,"r":1,"en":"Stamina cost for sprinting on dirt roads is reduced from 90% to 80%. Stamina cost for sprinting on stone roads is reduced from 75% to 50%.","d":"Sprinter sur les routes coûte moins d'endurance (chemins de terre : 80 % au lieu de 90 %, routes pavées : 50 % au lieu de 75 %).","tags":["explore"],"p":1},{"n":"Arachnoid","fr":"Arachnoïde","t":"Ranger","a":["Survivor"],"c":1,"r":3,"en":"At maximum rank (3): Stamina cost while climbing is reduced by 60%. Per rank: 20% cost reduction per level.","d":"Grimper coûte 20 % d'endurance en moins par rang (-60 % au rang 3).","tags":["explore"],"p":2},{"n":"Swiftshot Sustenance","fr":"Tir de récup. rapide","t":"Ranger","a":["Survivor"],"c":1,"r":3,"en":"At maximum rank (3): Defeating an enemy with a Bow has a 36% chance to spawn a Stamina Orb. Gathering an Orb restores 10% of the respective resource. Per rank: 12% chance per level.","d":"Tuer un ennemi à l'arc a 12 % de chances par rang (36 % au rang 3) de faire apparaître un orbe d'endurance.","tags":["bow"],"p":1},{"n":"Good Metabolism","fr":"Bon métabolisme","t":"Ranger","a":["Survivor"],"c":3,"r":1,"en":"Health, mana, and stamina Orbs restore 30% instead of 10% of their respective resource.\nMana and Health Potions restore 20% more.","d":"Les orbes de vie, mana et endurance rendent 30 % au lieu de 10 %. Les potions de vie et de mana rendent 20 % de plus.","tags":["survival"],"p":2},{"n":"Rebound","fr":"Rebond","t":"Ranger","a":["Survivor"],"c":2,"r":3,"en":"At maximum rank (3): Base Stamina Regeneration is increased by 30%. Per rank: 10% Stamina Regeneration per level.","d":"+10 % de régénération d'endurance de base par rang (+30 % au rang 3). Excellent pour tous les builds.","tags":["survival","melee","bow","dagger"],"p":3},{"n":"Sweet Tooth","fr":"Gourmand","t":"Ranger","a":["Survivor"],"c":3,"r":1,"en":"Stamina Regeneration of sweets is increased by 50%.","d":"La régénération d'endurance des sucreries est augmentée de 50 %.","tags":["survival"],"p":1},{"n":"Dessert Stomach","fr":"Estomac secondaire","t":"Ranger","a":["Survivor"],"c":4,"r":1,"en":"You gain one additional Food slot.","d":"+1 emplacement de nourriture (4 buffs de nourriture au lieu de 3). Un des meilleurs nœuds du jeu.","tags":["survival"],"p":3},{"n":"Double Jump","fr":"Double saut","t":"Ranger","a":["Survivor","Athlete"],"c":2,"r":1,"en":"Allows jumping a second time while airborne.","d":"Permet un second saut en l'air. Énorme pour l'exploration et le combat.","tags":["explore"],"p":3},{"n":"Crash Down: Force","fr":"Fracas force","t":"Ranger","a":["Survivor","Athlete"],"c":3,"r":1,"en":"When attacking from a double jump, Crash Down deals 20% more weapon damage.","d":"L'attaque plongeante (Fracas) depuis un double saut fait +20 % de dégâts d'arme.","tags":["melee"],"p":1},{"n":"Backstab Mastery","fr":"Coup de grâce","t":"Ranger","a":["Survivor","Athlete"],"c":1,"r":3,"en":"At maximum rank (3): Backstab damage is increased by 60%. Per rank: 20% damage per level.","d":"+20 % de dégâts dans le dos par rang (+60 % au rang 3).","tags":["dagger","stealth"],"p":2},{"n":"Spirit","fr":"Esprit","t":"Mage","a":["Trickster","Wizard","Healer","Battlemage"],"c":1,"r":1,"en":"Increases your Spirit attribute by 1\nIncreases Mana by 20 per Attribute Point","d":"Nœud d'attribut : +1 Esprit = +20 de mana.","tags":["magic"],"p":2},{"n":"Counterstrike","fr":"Contre-attaque","t":"Mage","a":["Trickster"],"c":1,"r":1,"en":"After receiving damage there is a 20% chance to reflect 50% of the damage back to the attacker as fire damage.\nThis magical attack can trigger other skills.","d":"Quand tu subis des dégâts : 20 % de chances d'en renvoyer 50 % à l'attaquant en dégâts de feu.","tags":["tank","magic"],"p":1},{"n":"Intelligence","fr":"Intelligence","t":"Mage","a":["Trickster","Healer","Battlemage"],"c":1,"r":1,"en":"Increases your Intelligence attribute by 1\nIncreases Magic damage by 5% per Attribute Point","d":"Nœud d'attribut : +1 Intelligence = +5 % de dégâts magiques (et soins plus forts).","tags":["magic","heal"],"p":2},{"n":"Begone","fr":"Va-t'en !","t":"Mage","a":["Trickster"],"c":3,"r":1,"en":"A magic-powered punch that pushes and stuns hit foes.\nReplaces your unarmed attacks as long as you have the necessary mana available: 30 Mana","d":"Remplace tes coups à mains nues par un coup de poing magique qui repousse et étourdit (30 mana).","tags":["magic"],"p":1},{"n":"Terror","fr":"Terreur","t":"Mage","a":["Trickster"],"c":2,"r":3,"en":"At maximum rank (3): Critical Strikes with spells have a 60% chance to stun the target for 2 seconds. Per rank: 20% chance per level.","d":"Les critiques de sorts ont 20 % de chances par rang (60 % au rang 3) d'étourdir la cible 2 secondes.","tags":["magic"],"p":2},{"n":"Arcane Concentration","fr":"Concentration d'arcane","t":"Mage","a":["Trickster"],"c":5,"r":1,"en":"Gain one point of Spirit for every two levels of the Flame.","d":"Tu gagnes 1 point d'Esprit tous les 2 niveaux de Flamme.","tags":["magic"],"p":2},{"n":"Shock Resistance","fr":"Résistance aux chocs","t":"Mage","a":["Trickster"],"c":1,"r":3,"en":"At maximum rank (3): Increases your Shock Resistance by 15%, which reduces the amount of Shock damage received. Per rank: 5% Resistance per level.","d":"+5 % de résistance à l'électricité par rang (+15 % au rang 3).","tags":["survival"],"p":1},{"n":"Quick Charge","fr":"Charge rapide","t":"Mage","a":["Wizard","Trickster"],"c":1,"r":1,"en":"Reduces the time Staffs require to charge-up a spell by 50%.","d":"Les bâtons chargent leurs sorts 50 % plus vite.","tags":["magic","staff"],"p":3},{"n":"Mage Apprenticeship","fr":"Apprentissage de mage","t":"Mage","a":["Wizard"],"c":2,"r":1,"en":"When attacking with a magical weapon all damage is increased by 10%.","d":"+10 % de dégâts avec toutes les armes magiques.","tags":["magic"],"p":3},{"n":"Iceman","fr":"Homme de glace","t":"Mage","a":["Wizard"],"c":2,"r":3,"en":"At maximum rank (3): All Ice damage is increased by 30%. Per rank: 10% damage per level.","d":"+10 % de dégâts de glace par rang (+30 % au rang 3).","tags":["magic","elem"],"p":2},{"n":"Thunder","fr":"Tonnerre","t":"Mage","a":["Wizard"],"c":2,"r":3,"en":"At maximum rank (3): All Shock damage is increased by 30%. Per rank: 10% damage per level.","d":"+10 % de dégâts de foudre par rang (+30 % au rang 3).","tags":["magic","elem"],"p":2},{"n":"Pyromaniac","fr":"Pyromane (Pyromaniac)","t":"Mage","a":["Wizard"],"c":3,"r":1,"en":"All fire damage is increased by an additional 20%.","d":"+20 % de dégâts de feu supplémentaires.","tags":["magic","elem"],"p":2},{"n":"Arsonist","fr":"Pyromane (Arsonist)","t":"Mage","a":["Wizard"],"c":2,"r":3,"en":"At maximum rank (3): All Fire damage is increased by 30%. Per rank: 10% damage per level.","d":"+10 % de dégâts de feu par rang (+30 % au rang 3).","tags":["magic","elem"],"p":2},{"n":"Lightning","fr":"Foudre","t":"Mage","a":["Wizard"],"c":3,"r":1,"en":"All shock damage is increased by an additional 20%.","d":"+20 % de dégâts de foudre supplémentaires.","tags":["magic","elem"],"p":2},{"n":"Subzero","fr":"Négatif","t":"Mage","a":["Wizard"],"c":3,"r":1,"en":"All ice damage is increased by an additional 20%.","d":"+20 % de dégâts de glace supplémentaires.","tags":["magic","elem"],"p":2},{"n":"Frost","fr":"Gel","t":"Mage","a":["Wizard"],"c":2,"r":1,"en":"When receiving melee damage, the attacker will be slowed down for 5 seconds.","d":"Quand tu subis un coup au corps à corps, l'attaquant est ralenti 5 secondes.","tags":["magic","tank"],"p":1},{"n":"Radiant Aura","fr":"Aura radieuse","t":"Mage","a":["Wizard"],"c":1,"r":3,"en":"At maximum rank (3): All Fell enemies within 3 meters take +3 Fire damage per Intelligence per second. Per rank: 1 meters range and +1 Fire damage per Intelligence per level.","d":"Les ennemis Corrompus (Fell) à moins de 1 à 3 m subissent des dégâts de feu chaque seconde selon ton Intelligence (+1 par rang).","tags":["magic"],"p":1},{"n":"Sun Aura","fr":"Aura du soleil","t":"Mage","a":["Wizard"],"c":2,"r":1,"en":"Upgrades Radiant Aura to deal 2 fire damage per intelligence.","d":"Améliore l'Aura radieuse : 2 dégâts de feu par point d'Intelligence.","tags":["magic"],"p":1},{"n":"Wizard","fr":"Magicien","t":"Mage","a":["Wizard"],"c":2,"r":3,"en":"At maximum rank (3): Critical Strike chance with Wands and Staves is increased by 6%. Per rank: 2% Critical Strike chance per level.","d":"+2 % de chances de critique avec baguettes et bâtons par rang (+6 % au rang 3).","tags":["magic","wand","staff"],"p":3},{"n":"Chain Hit","fr":"Coups enchaînés","t":"Mage","a":["Wizard"],"c":3,"r":1,"en":"Critical Strikes with Magic weapons hit an additional random target within 15 meters for 5 Shock damage per Intelligence. The initial target can be hit twice instead of chaining to another one.","d":"Les critiques avec une arme magique touchent une cible supplémentaire à moins de 15 m (5 dégâts de foudre par Intelligence).","tags":["magic"],"p":2},{"n":"Dark Arts","fr":"Arts obscurs","t":"Mage","a":["Wizard"],"c":2,"r":3,"en":"At maximum rank (3): All Shroud damage is increased by 30%. Per rank: 10% damage per level.","d":"+10 % de dégâts de Brume par rang (+30 % au rang 3).","tags":["magic","elem"],"p":1},{"n":"Mass Destruction","fr":"Destruction de masse","t":"Mage","a":["Wizard"],"c":3,"r":1,"en":"A critical attack with a magic weapon will hit all enemies within 20 meters of the target for 2 Shock damage per intelligence.","d":"Un critique avec une arme magique touche TOUS les ennemis à 20 m autour de la cible (2 dégâts de foudre par Intelligence).","tags":["magic"],"p":2},{"n":"Abyss","fr":"Abysse","t":"Mage","a":["Wizard"],"c":4,"r":1,"en":"All Shrouded damage is increased by an additional 20%.","d":"+20 % de dégâts de Brume supplémentaires.","tags":["magic","elem"],"p":1},{"n":"Fire Resistance","fr":"Résistance au feu","t":"Mage","a":["Wizard"],"c":1,"r":3,"en":"At maximum rank (3): Increases your Fire Resistance by 15%, which reduces the amount of Fire damage received. Per rank: 5% Resistance per level.","d":"+5 % de résistance au feu par rang (+15 % au rang 3).","tags":["survival"],"p":1},{"n":"Ice Resistance","fr":"Résistance à la glace","t":"Mage","a":["Wizard"],"c":1,"r":3,"en":"At maximum rank (3): Increases your Ice Resistance by 15%, which reduces the amount of Ice damage received. Per rank: 5% Resistance per level.","d":"+5 % de résistance à la glace par rang (+15 % au rang 3). Utile dans les Sommets d'Albaneve.","tags":["survival"],"p":1},{"n":"Necromancer","fr":"Nécromancien","t":"Mage","a":["Wizard","Healer"],"c":1,"r":3,"en":"At maximum rank (3): When killing an enemy with a Magic weapon, you have a 15% chance to summon a friendly Skull Companion. Per rank: 5% chance per level.","d":"Tuer un ennemi avec une arme magique a 5 % de chances par rang (15 % au rang 3) d'invoquer un crâne allié.","tags":["magic"],"p":1},{"n":"Healer","fr":"Guérisseur","t":"Mage","a":["Healer"],"c":1,"r":3,"en":"At maximum rank (3): Health gain from healing spells and Water Aura is increased by 45%. Per rank: 15% Healing per level.","d":"Les sorts de soin et l'Aura d'eau soignent +15 % par rang (+45 % au rang 3).","tags":["heal"],"p":3},{"n":"Healer II","fr":"Guérisseur ii","t":"Mage","a":["Healer"],"c":2,"r":1,"en":"Health gain from healing spells will be increased by 20%","d":"Les sorts de soin soignent +20 % de plus.","tags":["heal"],"p":2},{"n":"Water Aura","fr":"Aura de l'eau","t":"Mage","a":["Healer"],"c":1,"r":3,"en":"At maximum rank (3): You emit a healing aura that heals you and all injured allies within 15 meters. The healing scales with your Intelligence attribute and restores 1 Health per 2 points of Intelligence. Per rank: 5 meters range per level.","d":"Tu émets une aura qui soigne toi et tes alliés blessés autour (portée +5 m par rang, 15 m au rang 3). Soin : 1 PV par 2 points d'Intelligence.","tags":["heal","coop"],"p":3},{"n":"Waters Of Life","fr":"Eaux de la vie","t":"Mage","a":["Healer"],"c":2,"r":1,"en":"Increases Water Aura healing to 2 Health per 2 points of Intelligence.","d":"L'Aura d'eau soigne 2 PV par 2 points d'Intelligence (double).","tags":["heal"],"p":2},{"n":"Divine Surge","fr":"Déferlement divin","t":"Mage","a":["Healer"],"c":4,"r":1,"en":"Healing spells can perform Critical Strikes that scale with your Critical Strike damage.","d":"Tes sorts de soin peuvent faire des coups critiques (soins critiques).","tags":["heal"],"p":2},{"n":"Righteous Fire","fr":"Feu vertueux","t":"Mage","a":["Healer"],"c":2,"r":3,"en":"At maximum rank (3): Healing any target with a spell triggers a burst of fire that deals 60% of the heal amount as Fire damage to nearby Fell enemies. Per rank: 20% Fire damage per level.","d":"Soigner avec un sort déclenche une explosion de feu infligeant 20 % par rang (60 % au rang 3) du soin aux Corrompus proches.","tags":["heal","magic"],"p":2},{"n":"Healing Revive","fr":"Résurrection","t":"Mage","a":["Healer"],"c":1,"r":3,"en":"At maximum rank (3): Revive players with 24% increased Health. Default Health of revived players is 10%. Per rank: 8% Health per level.","d":"Les joueurs que tu relèves reviennent avec +8 % de vie par rang (+24 % au rang 3).","tags":["heal","coop"],"p":1},{"n":"Shroud Filter","fr":"Filtre de brume","t":"Mage","a":["Healer"],"c":3,"r":1,"en":"Dealing magic weapon damage has a 15% chance to trigger a small flame burst that restores 30 seconds of Shroud Time to you and your allies within 20 meters.\nShroud Time\nShould this time run out, the Shroud will consume you.","d":"Infliger des dégâts magiques a 15 % de chances de rendre 30 s de temps de Brume à toi et tes alliés à 20 m.","tags":["magic","explore"],"p":2},{"n":"Martyr","fr":"Martyr","t":"Mage","a":["Healer"],"c":3,"r":1,"en":"When you are killed by an enemy, all allies within 30 meters are healed 50% of their maximum health.\nAdditionally, they receive a Final Blessing buff, which increases their maximum Health by 100 for 15 minutes.","d":"Quand tu meurs, tes alliés à 30 m sont soignés de 50 % et gagnent +100 PV max pendant 15 minutes.","tags":["heal","coop"],"p":1},{"n":"Exalted","fr":"Exalté","t":"Mage","a":["Healer"],"c":5,"r":1,"en":"Gain one point of Intelligence for every two levels of the Flame.","d":"Tu gagnes 1 point d'Intelligence tous les 2 niveaux de Flamme. Gros bonus passif pour les mages.","tags":["magic","heal"],"p":3},{"n":"Blink","fr":"Flash","t":"Mage","a":["Healer","Battlemage"],"c":4,"r":1,"en":"Replaces the Dodge Roll ability with a short range teleport.","d":"Remplace la roulade d'esquive par une courte téléportation (Flash). Très puissant.","tags":["magic"],"p":3},{"n":"Blink Attack","fr":"Attaque flash","t":"Mage","a":["Healer","Battlemage"],"c":2,"r":1,"en":"Blinking into an enemy triggers an explosion which deals fire damage in a small range.\nDamage and mana cost scale with the intelligence attribute.","d":"Se téléporter à travers un ennemi déclenche une petite explosion de feu (dégâts et coût en mana selon l'Intelligence).","tags":["magic"],"p":2},{"n":"Emergency Blink","fr":"Flash d'urgence","t":"Mage","a":["Healer","Battlemage"],"c":2,"r":1,"en":"You can blink while being stunned. This will break the stunned state.","d":"Tu peux utiliser Flash même étourdi, ce qui casse l'étourdissement.","tags":["magic"],"p":2},{"n":"Shroud Resistance","fr":"Résistance au brume","t":"Mage","a":["Healer","Battlemage"],"c":1,"r":3,"en":"At maximum rank (3): Increases your Shroud Resistance by 15%, which reduces the amount of Shroud damage received. Per rank: 5% Resistance per level.","d":"+5 % de résistance aux dégâts de Brume par rang (+15 % au rang 3).","tags":["survival"],"p":1},{"n":"Shared Misery","fr":"Misère partagée","t":"Mage","a":["Healer","Battlemage"],"c":2,"r":1,"en":"When you receive Shroud damage, all players within 20-meters receive 15% increased Shroud Resistance for 30 seconds.","d":"Quand tu subis des dégâts de Brume, les joueurs à 20 m gagnent +15 % de résistance à la Brume pendant 30 s.","tags":["coop"],"p":1},{"n":"Unity","fr":"Unité","t":"Mage","a":["Battlemage"],"c":1,"r":3,"en":"At maximum rank (3): Damaging enemies with Wands has a 6% chance to restore 30% of your maximum Mana. Per rank: 2% chance and 10% of maximum Mana per level.","d":"Toucher avec une baguette a 2 % de chances par rang (6 % au rang 3) de rendre 10 % (30 % au rang 3) de ton mana max.","tags":["wand"],"p":2},{"n":"Wand Master","fr":"Maître de la baguette","t":"Mage","a":["Battlemage"],"c":3,"r":1,"en":"Attacking with a wand has a 30% chance to spawn an additional wand projectile that deals 50% damage.","d":"Attaquer avec une baguette a 30 % de chances de lancer un projectile bonus (50 % des dégâts).","tags":["wand"],"p":3},{"n":"Sting","fr":"Piqûre","t":"Mage","a":["Battlemage"],"c":3,"r":1,"en":"Repeated Wand damage is increased by 20%.","d":"Les dégâts répétés de baguette sont augmentés de 20 %.","tags":["wand"],"p":3},{"n":"Eternal Spark","fr":"Étincelle éternelle","t":"Mage","a":["Battlemage"],"c":1,"r":3,"en":"At maximum rank (3): Dealing damage with Wand projectiles has a 45% chance to restore 1 durability to that weapon. Per rank: 15% chance per level.","d":"Les projectiles de baguette ont 15 % de chances par rang (45 % au rang 3) de rendre 1 point de durabilité.","tags":["wand"],"p":1},{"n":"Life Burst","fr":"Explosion de vie","t":"Mage","a":["Battlemage"],"c":4,"r":1,"en":"When killing an enemy with a magic weapon all players within 15 meters of the target gain health equal to 3 times your Intelligence.","d":"Tuer un ennemi avec une arme magique soigne tous les joueurs à 15 m de 3 × ton Intelligence.","tags":["magic","heal","coop"],"p":2},{"n":"Life Essences","fr":"Essences de vie","t":"Mage","a":["Battlemage"],"c":1,"r":3,"en":"At maximum rank (3): Increases your maximum Health by +3 times your Intelligence attribute. Per rank: +1 times per level.","d":"Augmente ta vie max de +1 × ton Intelligence par rang (+3 × au rang 3). Rend les mages bien plus solides.","tags":["magic"],"p":3},{"n":"Arcane Deflection","fr":"Déviation des arcanes","t":"Mage","a":["Battlemage"],"c":1,"r":3,"en":"At maximum rank (3): Successfully parrying an enemy's attack restores 30 Mana. Parry You can block when equipped with any Melee weapon, Ward, or Shield. A well-timed block will parry the attack and fill up the enemy's Stun Bar. Wait to see a flash on the enemy or projectile to perform a parry. Per rank: 10 Mana per level.","d":"Une parade réussie rend 10 de mana par rang (30 au rang 3).","tags":["magic","parry"],"p":1},{"n":"Evasion Attack","fr":"Attaque d'évasion","t":"Mage","a":["Battlemage","Tank"],"c":4,"r":1,"en":"When equipped with a melee weapon, you can perform an evade attack which dashes towards the enemy and deals more weapon damage with [LMB].\nCost: 20 Stamina","d":"Arme de mêlée en main : après une esquive, [Clic gauche] te fait foncer sur l'ennemi pour une attaque renforcée (20 endurance).","tags":["melee"],"p":2},{"n":"Battle Heal","fr":"Soins de combat","t":"Mage","a":["Battlemage","Tank"],"c":2,"r":3,"en":"At maximum rank (3): Critical Strikes with Melee weapons heal you for 3% of your maximum Health. Per rank: 1% of maximum Health per level.","d":"Les critiques au corps à corps te soignent de 1 % de ta vie max par rang (3 % au rang 3).","tags":["melee","tank"],"p":2},{"n":"Bloodletting","fr":"Saignée","t":"Mage","a":["Battlemage","Tank"],"c":2,"r":1,"en":"When scoring a critical hit with a magical weapon, there is a 50% chance to spawn 2 health, mana, and/or stamina Orbs.\nGathering the Orb replenishes 10% of the respective resource.","d":"Un critique avec une arme magique a 50 % de chances de faire apparaître 2 orbes (vie, mana ou endurance) rendant 10 %.","tags":["magic"],"p":2},{"n":"Blood Magic","fr":"Magie du sang","t":"Mage","a":["Battlemage","Tank"],"c":4,"r":1,"en":"When your mana drops below 20%, you restore up to 25% of your max mana at the cost of 1 health per mana.\nThis effect stops at 1 health.\nCooldown: 2 minutes","d":"Si ton mana tombe sous 20 %, tu récupères jusqu'à 25 % de ton mana max en échange de 1 PV par point de mana (recharge 2 min).","tags":["magic"],"p":1},{"n":"Constitution","fr":"Constitution","t":"Warrior","a":["Tank","Warrior","Barbarian","Athlete"],"c":1,"r":1,"en":"Increases your Constitution attribute by 1\nIncreases Health by 50 per Attribute Point","d":"Nœud d'attribut : +1 Constitution = +50 points de vie.","tags":["tank","melee"],"p":2},{"n":"Shiny Plates","fr":"Plaques brillantes","t":"Warrior","a":["Tank"],"c":1,"r":3,"en":"At maximum rank (3): Magical Armor points from equipped items are increased by 12%. Per rank: 4% increased Magical Armor per level.","d":"+4 % d'armure magique de l'équipement par rang (+12 % au rang 3).","tags":["tank"],"p":2},{"n":"Heavy Plates","fr":"Plaques renforcées","t":"Warrior","a":["Tank"],"c":1,"r":3,"en":"At maximum rank (3): Physical Armor points from equipped items are increased by 12%. Per rank: 4% increased Physical Armor per level.","d":"+4 % d'armure physique de l'équipement par rang (+12 % au rang 3).","tags":["tank"],"p":2},{"n":"Warden","fr":"Gardien","t":"Warrior","a":["Tank"],"c":3,"r":1,"en":"While there are three or more enemies within 20 meters, you receive 10% increased Magical Resistance.","d":"S'il y a 3 ennemis ou plus à moins de 20 m, +10 % de résistance magique.","tags":["tank"],"p":1},{"n":"Tower","fr":"Tour","t":"Warrior","a":["Tank"],"c":3,"r":1,"en":"While there are three or more enemies within 20 meters, you receive 10% increased Physical Resistance.","d":"S'il y a 3 ennemis ou plus à moins de 20 m, +10 % de résistance physique.","tags":["tank"],"p":1},{"n":"Strength","fr":"Force","t":"Warrior","a":["Tank","Warrior","Barbarian","Athlete"],"c":1,"r":1,"en":"Increases your Strength attribute by 1\nIncreases Melee damage by 5% per Attribute Point","d":"Nœud d'attribut : +1 Force = +5 % de dégâts au corps à corps.","tags":["melee"],"p":2},{"n":"Nemesis","fr":"Némésis","t":"Warrior","a":["Tank"],"c":2,"r":3,"en":"At maximum rank (3): Increase the attention you draw from enemies by 75%. Per rank: 25% attention drawn per level.","d":"Tu attires +25 % d'attention des ennemis par rang (+75 % au rang 3). Pour tanker en coop.","tags":["tank","coop"],"p":1},{"n":"Arch Nemesis","fr":"Ennemi juré","t":"Warrior","a":["Tank"],"c":3,"r":1,"en":"Whenever an ally draws the attention of an enemy, you draw twice as much.","d":"Quand un allié attire l'attention d'un ennemi, tu en attires deux fois plus (rôle de tank en coop).","tags":["tank","coop"],"p":1},{"n":"Earth Aura","fr":"Aura de la terre","t":"Warrior","a":["Tank"],"c":2,"r":1,"en":"You emit a protective aura that reduces all incoming damage by 10% for you and allies within 10 meters.","d":"Aura protectrice : -10 % de dégâts subis pour toi et tes alliés à moins de 10 m.","tags":["tank","coop"],"p":3},{"n":"Thick Skin","fr":"Peau dure","t":"Warrior","a":["Tank"],"c":5,"r":1,"en":"Gain one point of Constitution for every two levels of the Flame.","d":"Tu gagnes 1 point de Constitution tous les 2 niveaux de Flamme.","tags":["tank","melee"],"p":3},{"n":"Wet Dog","fr":"Chien mouillé","t":"Warrior","a":["Tank"],"c":3,"r":1,"en":"Weakens the effect of the Wet and Soaked debuffs.\nStamina and Stamina Regeneration are reduced by 20% instead of 30%.\nWet\nReduces Stamina and Stamina Regeneration by 30% for 15 minutes. Warmth reduces the remaining duration.\nSoaked\nReduces Stamina and Stamina Regeneration by 30% for 30 seconds. Also reduces Ice and Shock Resistances by 30% but increases Fire Resistances by 30%.\nSoaked can be applied to enemies. \nSoaked duration can not be reduced by warmth and Wet debuff starts after it is over.","d":"Réduit les malus « Mouillé » et « Trempé » : endurance et régénération réduites de 20 % au lieu de 30 %.","tags":["survival"],"p":1},{"n":"Soaked Dog","fr":"Chien trempé","t":"Warrior","a":["Tank"],"c":3,"r":1,"en":"Weakens the effect of the Wet and Soaked debuffs.\nStamina and Stamina Regeneration are reduced by 10% instead of 20%.\nWet\nReduces Stamina and Stamina Regeneration by 30% for 15 minutes. Warmth reduces the remaining duration.\nSoaked\nReduces Stamina and Stamina Regeneration by 30% for 30 seconds. Also reduces Ice and Shock Resistances by 30% but increases Fire Resistances by 30%.\nSoaked can be applied to enemies. \nSoaked duration can not be reduced by warmth and Wet debuff starts after it is over.","d":"Réduit encore les malus « Mouillé » et « Trempé » : endurance et régénération réduites de 10 % au lieu de 20 %.","tags":["survival"],"p":1},{"n":"Splash Dash","fr":"Esquive plongée","t":"Warrior","a":["Tank"],"c":3,"r":1,"en":"Allows you to perform an evasive dash while swimming or diving.\nCost: 40 Stamina","d":"Permet une esquive rapide en nageant ou en plongée (40 endurance). Utile au Bassin des eaux voilées.","tags":["explore"],"p":1},{"n":"Absorb","fr":"Absorbption","t":"Warrior","a":["Tank"],"c":1,"r":3,"en":"At maximum rank (3): When you receive Magic damage, you have a 12% chance to restore 1 Mana per Health point lost. Per rank: 4% chance per level.","d":"Quand tu subis des dégâts magiques : 4 % de chances par rang (12 % au rang 3) de récupérer 1 mana par PV perdu.","tags":["tank","magic"],"p":1},{"n":"Snap","fr":"Craquage","t":"Warrior","a":["Tank"],"c":2,"r":1,"en":"Triggering a Merciless Attack restores 20% Mana.","d":"Déclencher une Attaque impitoyable rend 20 % de mana.","tags":["melee","magic"],"p":1},{"n":"Soul Leech","fr":"Absorbption d'âme","t":"Warrior","a":["Tank"],"c":2,"r":3,"en":"At maximum rank (3): When killing an enemy with a Melee weapon, all players within 45 meters of the target restore 15 Mana. Per rank: 15 meters range and 5 Mana per level.","d":"Tuer un ennemi au corps à corps rend 5 mana par rang (15 au rang 3) aux joueurs proches.","tags":["melee","coop"],"p":1},{"n":"Purification","fr":"Purification","t":"Warrior","a":["Tank","Warrior"],"c":1,"r":1,"en":"After defeating a Shroud infested foe with a melee weapon you replenish +5 seconds of Shroud Time.\nShroud Time\nShould this time run out, the Shroud will consume you.","d":"Tuer un ennemi de la Brume au corps à corps rend +5 secondes de temps de Brume.","tags":["melee","explore"],"p":2},{"n":"The Warrior's Path","fr":"La voie du guerrier","t":"Warrior","a":["Warrior"],"c":2,"r":1,"en":"When attacking with a melee weapon all damage is increased by 10%.","d":"+10 % de dégâts avec toutes les armes de corps à corps.","tags":["melee"],"p":3},{"n":"Thrust","fr":"Estocade","t":"Warrior","a":["Warrior"],"c":2,"r":3,"en":"At maximum rank (3): Melee Piercing damage is increased by 30%. Per rank: 10% damage per level.","d":"+10 % de dégâts perforants au corps à corps par rang (+30 % au rang 3) (lances, rapières…).","tags":["melee"],"p":1},{"n":"Brute","fr":"Brute (Brute)","t":"Warrior","a":["Warrior"],"c":2,"r":3,"en":"At maximum rank (3): Melee Blunt damage is increased by 30%. Per rank: 10% damage per level.","d":"+10 % de dégâts contondants au corps à corps par rang (+30 % au rang 3) (masses, marteaux).","tags":["melee","2h"],"p":2},{"n":"Slasher","fr":"Coupe-jarret","t":"Warrior","a":["Warrior"],"c":2,"r":3,"en":"At maximum rank (3): Melee Cutting damage is increased by 30%. Per rank: 10% damage per level.","d":"+10 % de dégâts tranchants au corps à corps par rang (+30 % au rang 3) (épées, haches).","tags":["melee","1h","2h"],"p":3},{"n":"Hammer Time","fr":"Si j'avais un marteau","t":"Warrior","a":["Warrior"],"c":3,"r":1,"en":"All melee blunt damage is increased by an additional 20%.","d":"+20 % de dégâts contondants au corps à corps.","tags":["melee","2h"],"p":2},{"n":"Pierce","fr":"Perforation","t":"Warrior","a":["Warrior"],"c":3,"r":1,"en":"All melee piercing damage is increased by an additional 20%.","d":"+20 % de dégâts perforants au corps à corps.","tags":["melee"],"p":1},{"n":"Butcher","fr":"Boucher","t":"Warrior","a":["Warrior"],"c":3,"r":1,"en":"All melee cutting damage is increased by an additional 20%.","d":"+20 % de dégâts tranchants au corps à corps.","tags":["melee","1h","2h"],"p":3},{"n":"Veteran","fr":"Vétéran","t":"Warrior","a":["Warrior"],"c":2,"r":3,"en":"At maximum rank (3): Critical Strike chance with One- or Two-Handed Axes, Clubs, Hammers, Swords, Greatswords and Daggers is increased by 6%. Per rank: 2% Critical Strike chance per level.","d":"+2 % de chances de critique avec haches, masses, marteaux, épées, espadons et dagues par rang (+6 % au rang 3).","tags":["melee","dagger"],"p":3},{"n":"Titan Edge","fr":"Bord en titane","t":"Warrior","a":["Warrior"],"c":1,"r":3,"en":"At maximum rank (3): Damage with Two-Handed Greatswords is increased by 15%. Per rank: 5% damage per level.","d":"+5 % de dégâts avec les espadons (épées à deux mains) par rang (+15 % au rang 3).","tags":["2h"],"p":2},{"n":"Swift Blades","fr":"Lames rapides","t":"Warrior","a":["Warrior"],"c":4,"r":1,"en":"Increases the attack speed of all One-Handed Melee weapons by 15%.","d":"+15 % de vitesse d'attaque avec toutes les armes à une main.","tags":["1h"],"p":3},{"n":"Feast","fr":"Festin","t":"Warrior","a":["Warrior","Barbarian"],"c":3,"r":1,"en":"Meat now increases health by an additional 15%.","d":"La viande rend 15 % de vie en plus.","tags":["survival","melee"],"p":1},{"n":"Steadfast","fr":"Inébranlable","t":"Warrior","a":["Warrior","Barbarian"],"c":2,"r":3,"en":"At maximum rank (3): Defeating an enemy with a Melee weapon restores 3 durability to that weapon. Per rank: 1 durability per level.","d":"Tuer un ennemi au corps à corps rend 1 point de durabilité à l'arme par rang (3 au rang 3).","tags":["melee"],"p":1},{"n":"Heavy Handed","fr":"Main lourde","t":"Warrior","a":["Barbarian"],"c":1,"r":3,"en":"At maximum rank (3): Filling up enemy Stun Bars is increased by 30% when attacking blocking enemies with Melee weapons. Overpower Attacking blocking enemies or parrying their attacks fills their Stun Bar until they become overpowered. Overpowered enemies are open for Merciless Attacks. Per rank: 10% effect per level.","d":"Frapper un ennemi qui bloque remplit sa jauge d'étourdissement de +10 % par rang (+30 % au rang 3).","tags":["melee","2h","parry"],"p":2},{"n":"Relentless","fr":"Acharné","t":"Warrior","a":["Barbarian"],"c":5,"r":1,"en":"Critical Strikes with Two-Handed weapons increase your Critical Strike chance by 8% for the next hit.","d":"Un critique avec une arme à deux mains donne +8 % de chances de critique au coup suivant.","tags":["2h"],"p":2},{"n":"Breach","fr":"Brèche","t":"Warrior","a":["Barbarian"],"c":3,"r":1,"en":"An overpowered enemy suffers 100% more melee damage for 3 seconds.\nOverpower\nTo overpower an enemy, fill their stun bar by attacking while they block or by parrying their attacks.","d":"Un ennemi « submergé » subit +100 % de dégâts au corps à corps pendant 3 secondes.","tags":["melee","parry"],"p":3},{"n":"Shockwave","fr":"Onde de choc","t":"Warrior","a":["Barbarian"],"c":3,"r":1,"en":"Trigger a shockwave when you parry an attack or overpower an enemy.\nThe shockwave pushes back nearby enemies. It also increases their stun bar, scaling with your strength attribute.\nOverpower\nTo overpower an enemy, fill their stun bar by attacking while they block or by parrying their attacks.","d":"Parer ou submerger un ennemi déclenche une onde de choc qui repousse les ennemis proches et remplit leur jauge d'étourdissement (selon la Force).","tags":["melee","parry"],"p":2},{"n":"Heavy Specialization","fr":"Spécialisation lourde","t":"Warrior","a":["Barbarian"],"c":5,"r":1,"en":"Allows you to attack faster with Two-Handed weapons.","d":"Tu attaques plus vite avec les armes à deux mains.","tags":["2h"],"p":3},{"n":"Whirlwind Crescendo","fr":"Tourbillon crescendo","t":"Warrior","a":["Barbarian"],"c":3,"r":1,"en":"When equipped with a Two-Handed weapon, trigger a whirl attack at the end of an attack chain.\nCost: 75 Stamina","d":"Arme à deux mains : déclenche une attaque tourbillon à la fin d'un enchaînement (75 endurance).","tags":["2h"],"p":2},{"n":"Barbarian","fr":"Barbare","t":"Warrior","a":["Barbarian"],"c":5,"r":1,"en":"Gain one point of Strength for every two levels of the Flame.","d":"Tu gagnes 1 point de Force tous les 2 niveaux de Flamme. Gros bonus passif pour le corps à corps.","tags":["melee"],"p":3},{"n":"Blood Rage","fr":"Rage sanguinaire","t":"Warrior","a":["Barbarian"],"c":2,"r":1,"en":"When an enemy is killed within 10 meters with a melee weapon, the damage done with melee weapons is increased by 20% for 10 seconds.","d":"Tuer un ennemi au corps à corps à moins de 10 m donne +20 % de dégâts de mêlée pendant 10 secondes.","tags":["melee"],"p":2},{"n":"Bash","fr":"Le cambriolage","t":"Warrior","a":["Barbarian","Athlete"],"c":2,"r":3,"en":"At maximum rank (3): Parrying enemy attacks bashes them for 30 Blunt damage. Bash damage is increased by your Strength attribute. Parry You can block when equipped with any Melee weapon, Ward, or Shield. A well-timed block will parry the attack and fill up the enemy's Stun Bar. Wait to see a flash on the enemy or projectile to perform a parry. Per rank: 10 Blunt damage per level.","d":"Une parade réussie frappe l'ennemi pour 10 dégâts contondants par rang (30 au rang 3), augmentés par ta Force.","tags":["melee","parry","1h"],"p":1},{"n":"Crash Down Attack","fr":"Attaque fracassante","t":"Warrior","a":["Athlete"],"c":3,"r":1,"en":"When equipped with a Melee weapon, you can perform a jump attack during the descent of your jump.\nCrash Down deals 50% more weapon damage in a small blast radius and costs Stamina according to the weapon's weight.\nCost: 35-60 Stamina\nBlock Breaker\nThis special attack fills a blocking enemy's Stun Bar twice as much when hit.","d":"Arme de mêlée : attaque plongeante pendant la descente d'un saut, +50 % de dégâts dans une petite zone (35 à 60 endurance). Remplit fortement la jauge d'étourdissement.","tags":["melee"],"p":2},{"n":"Upwards Slash Attack","fr":"Attaque en coup vers le haut","t":"Warrior","a":["Athlete"],"c":3,"r":1,"en":"When equipped with a Melee weapon, launch a powerful upward strike during the ascent of your jump.\nUse this skill to rapidly close the distance on flying enemies.\nCost: 25 Stamina","d":"Arme de mêlée : puissant coup vers le haut pendant la montée d'un saut (25 endurance). Idéal contre les volants.","tags":["melee"],"p":1},{"n":"Kick","fr":"Coup de pied","t":"Warrior","a":["Athlete"],"c":3,"r":1,"en":"When equipped with a Melee weapon you can perform a Kick by attacking while blocking.\nKick deals little damage but hits the target with massive force to fill up the enemies Stun Bar and pushes them back.\nStun Bar increase scales with Dexterity. Stun time depends on the enemy's size.\nOverpower\nAttacking blocking enemies or parrying their attacks fills their Stun Bar until they become overpowered.\nOverpowered enemies are open for Merciless Attacks.","d":"En bloquant, attaque pour donner un coup de pied : peu de dégâts mais remplit fortement la jauge d'étourdissement et repousse (selon la Dextérité).","tags":["melee","dagger","parry"],"p":2},{"n":"Vigorous Deflection","fr":"Déflexion rigoureuse","t":"Warrior","a":["Athlete"],"c":1,"r":3,"en":"At maximum rank (3): Successfully parrying an enemy's attack restores 45 Stamina. Parry You can block when equipped with any Melee weapon, Ward, or Shield. A well-timed block will parry the attack and fill up the enemy's Stun Bar. Wait to see a flash on the enemy or projectile to perform a parry. Per rank: 15 Stamina per level.","d":"Une parade réussie rend 15 d'endurance par rang (45 au rang 3).","tags":["melee","parry"],"p":2},{"n":"Blood Warrior","fr":"Guerrier sanguinaire","t":"Warrior","a":["Athlete"],"c":3,"r":1,"en":"Spawn a health orb after defeating an enemy with a Sneak Attack or Merciless Attack.\nGathering the orbs replenishes 10% of your health.","d":"Tuer un ennemi avec une Attaque furtive ou impitoyable fait apparaître un orbe de vie (rend 10 % de vie).","tags":["melee","stealth"],"p":1},{"n":"Finesse","fr":"Finesse","t":"Warrior","a":["Athlete"],"c":1,"r":3,"en":"At maximum rank (3): Dealing damage with One-Handed Swords, One-Handed Axes, One-Handed Clubs or Daggers has a 45% chance to restore 1 durability to that weapon. Per rank: 15% chance per level.","d":"Armes à une main et dagues : 15 % de chances par rang (45 % au rang 3) de regagner 1 de durabilité en frappant.","tags":["1h","dagger"],"p":1},{"n":"Last Meal","fr":"Dernier repas","t":"Warrior","a":["Athlete"],"c":5,"r":1,"en":"Your Food buffs persist through death, but they last half as long.","d":"Tes buffs de nourriture persistent après la mort, mais durent moitié moins longtemps.","tags":["survival"],"p":1},{"n":"Dagger Master","fr":"Maître de la dague","t":"Warrior","a":["Athlete"],"c":3,"r":1,"en":"Increases damage dealt with daggers by 15%.","d":"+15 % de dégâts avec les dagues.","tags":["dagger"],"p":3},{"n":"Slice And Dice","fr":"Trancher et découper","t":"Warrior","a":["Athlete"],"c":3,"r":1,"en":"Increases the damage of your next bow attack by 50% after a dagger crit.","d":"Après un critique à la dague, ta prochaine attaque à l'arc fait +50 % de dégâts.","tags":["dagger","bow"],"p":2},{"n":"Poisoned Blades","fr":"Lames venimeuses","t":"Warrior","a":["Athlete"],"c":3,"r":1,"en":"Increases the chance to poison enemies to 25% when using daggers with the Poisoned Blades perk.","d":"Avec des dagues ayant l'atout « Lames empoisonnées », 25 % de chances d'empoisonner.","tags":["dagger"],"p":2},{"n":"Poison Mastery","fr":"Maîtrise du venin","t":"Warrior","a":["Athlete"],"c":4,"r":1,"en":"Increases the damage dealt with the Poisoned Blades dagger perk by 100%.","d":"+100 % de dégâts pour l'atout de dague « Lames empoisonnées ».","tags":["dagger"],"p":2},{"n":"Quick Reflex Block","fr":"Bloc réflexe rapide","t":"Warrior","a":["Athlete"],"c":3,"r":1,"en":"Briefly increases your Block value when blocking with Daggers, ensuring a near-miss parry reduces Stamina minimally.","d":"Augmente brièvement ton blocage avec les dagues : une parade ratée de peu coûte très peu d'endurance.","tags":["dagger","parry"],"p":1},{"n":"Expose Weakness","fr":"Exposez les faiblesses","t":"Warrior","a":["Athlete"],"c":4,"r":1,"en":"Critical Strikes with Daggers increase damage dealt to the enemy by 25% for 3 seconds.","d":"Les critiques à la dague augmentent les dégâts subis par l'ennemi de 25 % pendant 3 secondes.","tags":["dagger"],"p":2},{"n":"One-Handed Specialization","fr":"One-Handed Specialization","t":"Warrior","a":["Guardian"],"c":3,"r":1,"en":"Unlocks Special Abilities for One-Handed Melee weapons.\nPress [R] to unleash a powerful Special Ability after generating enough Focus.","d":"Débloque les capacités spéciales des armes à une main : attaque pour générer de la Concentration, puis [R] pour une capacité puissante.","tags":["1h","melee"],"p":3},{"n":"Barbarian's Path","fr":"Brute (Barbarian's Path)","t":"Warrior","a":["Barbarian"],"c":1,"r":3,"en":"All Two-Handed Melee weapon damage is increased by 5% (per level).","d":"+5 % de dégâts avec les armes de corps à corps à deux mains par rang.","tags":["2h"],"p":3},{"n":"Felling Axe Specialization","fr":"Felling Axe Specialization","t":"Core","a":["Core"],"c":3,"r":1,"en":"Unlocks Special Abilities of Felling Axes. Press [R] to unleash a powerful Special Ability after generating enough Focus.","d":"Débloque les capacités spéciales des haches d'abattage : génère de la Concentration en attaquant, puis [R] pour une capacité puissante.","tags":["gather"],"p":1}];
